// ============ CONSTANTS ============
const TILE = 16;
const WORLD_W = 400;
const WORLD_H = 200;
const GRAVITY = 0.5;
const JUMP_FORCE = -9;
const MOVE_SPEED = 3.5;
const REACH = 5;
const SURFACE_Y = 70;

// Block types
const B = {
  AIR:0, GRASS:1, DIRT:2, STONE:3, COAL:4, IRON:5, GOLD:6, DIAMOND:7,
  WOOD:8, LEAVES:9, SAND:10, BEDROCK:11, PLANK:12, TORCH:13, COBBLE:14,
  WATER:15, CRAFTING:16, CHEST:17
};

const BLOCK_DATA = {
  [B.AIR]:      { name:'空气',   color:null,       hardness:0,   drop:null,       solid:false, light:0 },
  [B.GRASS]:    { name:'草方块', color:'#4a8c3f',  hardness:3,   drop:B.DIRT,     solid:true,  light:0 },
  [B.DIRT]:     { name:'泥土',   color:'#8B6914',  hardness:2,   drop:B.DIRT,     solid:true,  light:0 },
  [B.STONE]:    { name:'石头',   color:'#808080',  hardness:5,   drop:B.COBBLE,   solid:true,  light:0 },
  [B.COAL]:     { name:'煤矿',   color:'#555555',  hardness:5,   drop:B.COAL,     solid:true,  light:0 },
  [B.IRON]:     { name:'铁矿',   color:'#c4a882',  hardness:6,   drop:B.IRON,     solid:true,  light:0 },
  [B.GOLD]:     { name:'金矿',   color:'#ffd700',  hardness:7,   drop:B.GOLD,     solid:true,  light:0 },
  [B.DIAMOND]:  { name:'钻石矿', color:'#00e5ff',  hardness:8,   drop:B.DIAMOND,  solid:true,  light:0 },
  [B.WOOD]:     { name:'木头',   color:'#8B5E3C',  hardness:3,   drop:B.WOOD,     solid:true,  light:0 },
  [B.LEAVES]:   { name:'树叶',   color:'#2d8a2d',  hardness:1,   drop:null,       solid:true,  light:0 },
  [B.SAND]:     { name:'沙子',   color:'#e8d68e',  hardness:2,   drop:B.SAND,     solid:true,  light:0 },
  [B.BEDROCK]:  { name:'基岩',   color:'#333333',  hardness:999, drop:null,       solid:true,  light:0 },
  [B.PLANK]:    { name:'木板',   color:'#c49a6c',  hardness:3,   drop:B.PLANK,    solid:true,  light:0 },
  [B.TORCH]:    { name:'火把',   color:'#ffaa00',  hardness:0.5, drop:B.TORCH,    solid:false, light:8 },
  [B.COBBLE]:   { name:'圆石',   color:'#6b6b6b',  hardness:5,   drop:B.COBBLE,   solid:true,  light:0 },
  [B.WATER]:    { name:'水',     color:'#3366cc',  hardness:0,   drop:null,       solid:false, light:0 },
  [B.CRAFTING]: { name:'工作台', color:'#b87333',  hardness:3,   drop:B.CRAFTING, solid:true,  light:0 },
  [B.CHEST]:    { name:'箱子',   color:'#8B6914',  hardness:3,   drop:B.CHEST,    solid:true,  light:0 },
};

// ============ NOISE ============
class SimplexNoise {
  constructor(seed) {
    this.p = new Uint8Array(512);
    const perm = new Uint8Array(256);
    for (let i = 0; i < 256; i++) perm[i] = i;
    let s = seed || Math.random() * 65536;
    for (let i = 255; i > 0; i--) {
      s = (s * 16807 + 0) % 2147483647;
      const j = s % (i + 1);
      [perm[i], perm[j]] = [perm[j], perm[i]];
    }
    for (let i = 0; i < 512; i++) this.p[i] = perm[i & 255];
  }
  noise2D(x, y) {
    const F2 = 0.5 * (Math.sqrt(3) - 1);
    const G2 = (3 - Math.sqrt(3)) / 6;
    const s = (x + y) * F2;
    const i = Math.floor(x + s), j = Math.floor(y + s);
    const t = (i + j) * G2;
    const X0 = i - t, Y0 = j - t;
    const x0 = x - X0, y0 = y - Y0;
    const i1 = x0 > y0 ? 1 : 0, j1 = x0 > y0 ? 0 : 1;
    const x1 = x0 - i1 + G2, y1 = y0 - j1 + G2;
    const x2 = x0 - 1 + 2 * G2, y2 = y0 - 1 + 2 * G2;
    const ii = i & 255, jj = j & 255;
    const grad = (hash, gx, gy) => {
      const h = hash & 7;
      const u = h < 4 ? gx : gy;
      const v = h < 4 ? gy : gx;
      return ((h & 1) ? -u : u) + ((h & 2) ? -v : v);
    };
    let n0 = 0, n1 = 0, n2 = 0;
    let t0 = 0.5 - x0*x0 - y0*y0;
    if (t0 >= 0) { t0 *= t0; n0 = t0 * t0 * grad(this.p[ii + this.p[jj]], x0, y0); }
    let t1 = 0.5 - x1*x1 - y1*y1;
    if (t1 >= 0) { t1 *= t1; n1 = t1 * t1 * grad(this.p[ii + i1 + this.p[jj + j1]], x1, y1); }
    let t2 = 0.5 - x2*x2 - y2*y2;
    if (t2 >= 0) { t2 *= t2; n2 = t2 * t2 * grad(this.p[ii + 1 + this.p[jj + 1]], x2, y2); }
    return 70 * (n0 + n1 + n2);
  }
  fbm(x, y, octaves = 4, lacunarity = 2, gain = 0.5) {
    let sum = 0, amp = 1, freq = 1, max = 0;
    for (let i = 0; i < octaves; i++) {
      sum += this.noise2D(x * freq, y * freq) * amp;
      max += amp;
      amp *= gain;
      freq *= lacunarity;
    }
    return sum / max;
  }
}

