// ============ WORLD ============
class World {
  constructor(seed) {
    this.seed = seed || Math.floor(Math.random() * 999999);
    this.noise = new SimplexNoise(this.seed);
    this.caveNoise = new SimplexNoise(this.seed + 1);
    this.oreNoise = new SimplexNoise(this.seed + 2);
    this.tiles = new Uint8Array(WORLD_W * WORLD_H);
    this.light = new Uint8Array(WORLD_W * WORLD_H);
    this.generate();
  }

  idx(x, y) { return y * WORLD_W + x; }
  inBounds(x, y) { return x >= 0 && x < WORLD_W && y >= 0 && y < WORLD_H; }

  get(x, y) {
    if (!this.inBounds(x, y)) return B.BEDROCK;
    return this.tiles[this.idx(x, y)];
  }

  set(x, y, type) {
    if (!this.inBounds(x, y)) return;
    this.tiles[this.idx(x, y)] = type;
  }

  isSolid(x, y) {
    const t = this.get(x, y);
    return BLOCK_DATA[t] ? BLOCK_DATA[t].solid : false;
  }

  generate() {
    // Generate heightmap
    const heights = new Float32Array(WORLD_W);
    for (let x = 0; x < WORLD_W; x++) {
      heights[x] = SURFACE_Y + 
        this.noise.fbm(x * 0.02, 0, 4) * 15 +
        this.noise.fbm(x * 0.005, 100, 2) * 8;
    }

    // Fill terrain
    for (let x = 0; x < WORLD_W; x++) {
      const surfaceH = Math.floor(heights[x]);
      for (let y = 0; y < WORLD_H; y++) {
        if (y < surfaceH) {
          this.set(x, y, B.AIR);
        } else if (y === surfaceH) {
          this.set(x, y, B.GRASS);
        } else if (y < surfaceH + 5 + Math.floor(this.noise.noise2D(x * 0.1, y * 0.1) * 3)) {
          this.set(x, y, B.DIRT);
        } else if (y >= WORLD_H - 2) {
          this.set(x, y, B.BEDROCK);
        } else {
          this.set(x, y, B.STONE);
        }
      }
    }

    // Generate caves
    for (let x = 0; x < WORLD_W; x++) {
      for (let y = Math.floor(SURFACE_Y) + 5; y < WORLD_H - 2; y++) {
        const cave1 = this.caveNoise.fbm(x * 0.05, y * 0.05, 3);
        const cave2 = this.caveNoise.fbm(x * 0.08, y * 0.08, 2);
        if (Math.abs(cave1) < 0.08 || Math.abs(cave2) < 0.06) {
          this.set(x, y, B.AIR);
        }
        // Large caverns
        const cavern = this.caveNoise.fbm(x * 0.02, y * 0.02, 2);
        if (cavern > 0.35 && y > SURFACE_Y + 30) {
          this.set(x, y, B.AIR);
        }
      }
    }

    // Generate ores
    for (let x = 0; x < WORLD_W; x++) {
      for (let y = 0; y < WORLD_H; y++) {
        if (this.get(x, y) !== B.STONE) continue;
        const depth = y - SURFACE_Y;
        const n = this.oreNoise.noise2D(x * 0.15, y * 0.15);
        const n2 = this.oreNoise.noise2D(x * 0.15 + 500, y * 0.15 + 500);
        if (depth > 5 && n > 0.6) this.set(x, y, B.COAL);
        if (depth > 20 && n2 > 0.65) this.set(x, y, B.IRON);
        if (depth > 40 && n > 0.7) this.set(x, y, B.GOLD);
        if (depth > 60 && n2 > 0.75) this.set(x, y, B.DIAMOND);
      }
    }

    // Generate trees
    for (let x = 5; x < WORLD_W - 5; x++) {
      const surfaceH = Math.floor(heights[x]);
      if (this.get(x, surfaceH) !== B.GRASS) continue;
      if (Math.random() > 0.12) continue;
      const treeH = 5 + Math.floor(Math.random() * 4);
      // Trunk
      for (let ty = 1; ty <= treeH; ty++) {
        this.set(x, surfaceH - ty, B.WOOD);
      }
      // Leaves
      const leafR = 2 + Math.floor(Math.random() * 2);
      for (let lx = -leafR; lx <= leafR; lx++) {
        for (let ly = -leafR - 1; ly <= 0; ly++) {
          if (Math.abs(lx) + Math.abs(ly) > leafR + 1) continue;
          const tx = x + lx, ty = surfaceH - treeH + ly;
          if (this.get(tx, ty) === B.AIR) {
            this.set(tx, ty, B.LEAVES);
          }
        }
      }
      x += 4 + Math.floor(Math.random() * 3);
    }

    // Generate sand patches near surface
    for (let x = 0; x < WORLD_W; x++) {
      const surfaceH = Math.floor(heights[x]);
      const sandN = this.noise.noise2D(x * 0.03, 50);
      if (sandN > 0.3) {
        this.set(x, surfaceH, B.SAND);
        if (surfaceH + 1 < WORLD_H) this.set(x, surfaceH + 1, B.SAND);
      }
    }

    // Update lighting
    this.updateLight();
  }

  updateLight() {
    this.light.fill(0);
    // Sky light
    for (let x = 0; x < WORLD_W; x++) {
      let light = 15;
      for (let y = 0; y < WORLD_H; y++) {
        const t = this.get(x, y);
        if (t === B.AIR || !BLOCK_DATA[t].solid) {
          this.light[this.idx(x, y)] = Math.max(this.light[this.idx(x, y)], light);
        } else {
          light = Math.max(0, light - 2);
        }
        if (light <= 0) break;
      }
    }
    // Torch light
    for (let x = 0; x < WORLD_W; x++) {
      for (let y = 0; y < WORLD_H; y++) {
        if (this.get(x, y) === B.TORCH) {
          this.spreadLight(x, y, 8);
        }
      }
    }
  }

  spreadLight(sx, sy, radius) {
    for (let dx = -radius; dx <= radius; dx++) {
      for (let dy = -radius; dy <= radius; dy++) {
        const dist = Math.sqrt(dx*dx + dy*dy);
        if (dist > radius) continue;
        const x = sx + dx, y = sy + dy;
        if (!this.inBounds(x, y)) continue;
        const l = Math.floor((1 - dist / radius) * 12);
        this.light[this.idx(x, y)] = Math.max(this.light[this.idx(x, y)], l);
      }
    }
  }

  getSpawnPoint() {
    const cx = Math.floor(WORLD_W / 2);
    for (let y = 0; y < WORLD_H; y++) {
      if (this.isSolid(cx, y)) return { x: cx * TILE + TILE/2, y: (y - 2) * TILE };
    }
    return { x: cx * TILE, y: SURFACE_Y * TILE };
  }
}

