// ============ PLAYER ============
class Player {
  constructor(x, y) {
    this.x = x; this.y = y;
    this.w = 12; this.h = 28;
    this.vx = 0; this.vy = 0;
    this.onGround = false;
    this.hp = 100; this.maxHp = 100;
    this.facing = 1;
    this.inventory = [
      { type: B.TORCH, count: 20 },
      { type: B.PLANK, count: 10 },
      { type: B.COBBLE, count: 0 },
      { type: B.WOOD, count: 0 },
      { type: B.DIRT, count: 0 },
      { type: B.SAND, count: 0 },
      { type: B.COAL, count: 0 },
      { type: B.IRON, count: 0 },
      { type: B.CRAFTING, count: 0 },
    ];
    this.activeSlot = 0;
    this.miningTarget = null;
    this.miningProgress = 0;
    this.invincible = 0;
    this.fallDist = 0;
    this.lastY = y;
  }

  getActiveItem() { return this.inventory[this.activeSlot]; }

  addItem(type, count = 1) {
    // Try stack existing
    for (let i = 0; i < this.inventory.length; i++) {
      if (this.inventory[i].type === type) {
        this.inventory[i].count += count;
        return true;
      }
    }
    // Try empty slot
    for (let i = 0; i < this.inventory.length; i++) {
      if (this.inventory[i].count <= 0) {
        this.inventory[i] = { type, count };
        return true;
      }
    }
    return false;
  }

  removeItem(slot, count = 1) {
    if (this.inventory[slot].count >= count) {
      this.inventory[slot].count -= count;
      if (this.inventory[slot].count <= 0) {
        this.inventory[slot].count = 0;
      }
      return true;
    }
    return false;
  }

  update(keys, world) {
    // Movement
    this.vx = 0;
    if (keys['KeyA'] || keys['ArrowLeft']) { this.vx = -MOVE_SPEED; this.facing = -1; }
    if (keys['KeyD'] || keys['ArrowRight']) { this.vx = MOVE_SPEED; this.facing = 1; }
    if ((keys['KeyW'] || keys['ArrowUp'] || keys['Space']) && this.onGround) {
      this.vy = JUMP_FORCE;
      this.onGround = false;
    }

    // Gravity
    this.vy += GRAVITY;
    if (this.vy > 12) this.vy = 12;

    // Track fall distance
    if (!this.onGround && this.vy > 0) {
      this.fallDist += this.vy;
    } else {
      if (this.fallDist > TILE * 15) {
        const dmg = Math.floor((this.fallDist - TILE * 15) / TILE * 5);
        if (dmg > 0) this.takeDamage(dmg);
      }
      this.fallDist = 0;
    }

    // Horizontal collision
    this.x += this.vx;
    this.resolveCollisionX(world);

    // Vertical collision
    this.lastY = this.y;
    this.y += this.vy;
    this.resolveCollisionY(world);

    // Invincibility timer
    if (this.invincible > 0) this.invincible--;

    // World bounds
    if (this.x < 0) this.x = 0;
    if (this.x > (WORLD_W - 1) * TILE) this.x = (WORLD_W - 1) * TILE;
    if (this.y > (WORLD_H - 3) * TILE) this.takeDamage(999);
  }

  resolveCollisionX(world) {
    const left = Math.floor(this.x / TILE);
    const right = Math.floor((this.x + this.w) / TILE);
    const top = Math.floor(this.y / TILE);
    const bottom = Math.floor((this.y + this.h - 1) / TILE);
    for (let ty = top; ty <= bottom; ty++) {
      for (let tx = left; tx <= right; tx++) {
        if (world.isSolid(tx, ty)) {
          if (this.vx > 0) {
            this.x = tx * TILE - this.w - 0.01;
          } else if (this.vx < 0) {
            this.x = (tx + 1) * TILE + 0.01;
          }
          this.vx = 0;
        }
      }
    }
  }

  resolveCollisionY(world) {
    const left = Math.floor(this.x / TILE);
    const right = Math.floor((this.x + this.w) / TILE);
    const top = Math.floor(this.y / TILE);
    const bottom = Math.floor((this.y + this.h - 1) / TILE);
    this.onGround = false;
    for (let ty = top; ty <= bottom; ty++) {
      for (let tx = left; tx <= right; tx++) {
        if (world.isSolid(tx, ty)) {
          if (this.vy > 0) {
            this.y = ty * TILE - this.h;
            this.onGround = true;
          } else if (this.vy < 0) {
            this.y = (ty + 1) * TILE + 0.01;
          }
          this.vy = 0;
        }
      }
    }
  }

  takeDamage(amount) {
    if (this.invincible > 0) return;
    this.hp = Math.max(0, this.hp - amount);
    this.invincible = 30;
    if (this.hp <= 0) {
      document.getElementById('death-screen').style.display = 'flex';
    }
  }

  render(ctx, cam) {
    const sx = this.x - cam.x;
    const sy = this.y - cam.y;

    // Flash when invincible
    if (this.invincible > 0 && Math.floor(this.invincible / 3) % 2) return;

    ctx.save();
    ctx.translate(sx + this.w/2, sy + this.h/2);
    ctx.scale(this.facing, 1);
    ctx.translate(-this.w/2, -this.h/2);

    // Body
    ctx.fillStyle = '#4488cc';
    ctx.fillRect(1, 8, 10, 12);

    // Head
    ctx.fillStyle = '#ffcc99';
    ctx.fillRect(2, 0, 8, 9);

    // Hair
    ctx.fillStyle = '#8B4513';
    ctx.fillRect(1, 0, 10, 3);
    ctx.fillRect(1, 0, 2, 5);

    // Eyes
    ctx.fillStyle = '#fff';
    ctx.fillRect(6, 3, 3, 2);
    ctx.fillStyle = '#333';
    ctx.fillRect(7, 4, 1, 1);

    // Legs
