function handleMining() {
  if (!mouse.left || !player || !world) return;

  const wx = Math.floor((mouse.x + camera.x) / TILE);
  const wy = Math.floor((mouse.y + camera.y) / TILE);

  // Check reach
  const px = Math.floor((player.x + player.w/2) / TILE);
  const py = Math.floor((player.y + player.h/2) / TILE);
  const dist = Math.sqrt((wx - px) ** 2 + (wy - py) ** 2);
  if (dist > REACH) return;

  const tile = world.get(wx, wy);
  if (tile === B.AIR || tile === B.BEDROCK) return;

  const data = BLOCK_DATA[tile];
  if (!data || data.hardness >= 999) return;

  // Mining target
  const targetKey = `${wx},${wy}`;
  if (player.miningTarget !== targetKey) {
    player.miningTarget = targetKey;
    player.miningProgress = 0;
  }

  player.miningProgress += 1;

  // Show mining bar
  const bar = document.getElementById('mining-bar');
  const fill = document.getElementById('mining-fill');
  bar.style.display = 'block';
  bar.style.left = (wx * TILE - camera.x + TILE/2 - 20) + 'px';
  bar.style.top = (wy * TILE - camera.y - 10) + 'px';
  fill.style.width = Math.min(100, (player.miningProgress / data.hardness) * 100) + '%';

  if (player.miningProgress >= data.hardness) {
    // Break block
    const dropType = data.drop !== null ? data.drop : tile;
    if (dropType !== null) player.addItem(dropType);
    world.set(wx, wy, B.AIR);
    spawnParticles(wx * TILE + TILE/2, wy * TILE + TILE/2, data.color, 10);
    player.miningProgress = 0;
    player.miningTarget = null;
    bar.style.display = 'none';
    world.updateLight();
    updateUI();
  }
}

function handlePlacing() {
  if (!mouse.right || !player || !world) return;
  mouse.right = false; // Single place per click

  const wx = Math.floor((mouse.x + camera.x) / TILE);
  const wy = Math.floor((mouse.y + camera.y) / TILE);

  // Check reach
  const px = Math.floor((player.x + player.w/2) / TILE);
  const py = Math.floor((player.y + player.h/2) / TILE);
  const dist = Math.sqrt((wx - px) ** 2 + (wy - py) ** 2);
  if (dist > REACH) return;

  // Can't place on existing block
  if (world.get(wx, wy) !== B.AIR) return;

  // Can't place inside player
  const pLeft = Math.floor(player.x / TILE);
  const pRight = Math.floor((player.x + player.w) / TILE);
  const pTop = Math.floor(player.y / TILE);
  const pBottom = Math.floor((player.y + player.h) / TILE);
  if (wx >= pLeft && wx <= pRight && wy >= pTop && wy <= pBottom) return;

  const item = player.getActiveItem();
  if (!item || item.count <= 0) return;

  const blockType = item.type;
  if (!BLOCK_DATA[blockType] || blockType === B.AIR) return;

  world.set(wx, wy, blockType);
  player.removeItem(player.activeSlot);
  world.updateLight();
  updateUI();
}

