  { result: B.CHEST, count: 1, ingredients: [{ type: B.PLANK, count: 8 }, { type: B.IRON, count: 2 }], name: '箱子' },
];

function canCraft(recipe) {
  for (const ing of recipe.ingredients) {
    let total = 0;
    for (const slot of player.inventory) {
      if (slot.type === ing.type) total += slot.count;
    }
    if (total < ing.count) return false;
  }
  return true;
}

function doCraft(recipe) {
  if (!canCraft(recipe)) return;
  for (const ing of recipe.ingredients) {
    let remaining = ing.count;
    for (let i = 0; i < player.inventory.length && remaining > 0; i++) {
      if (player.inventory[i].type === ing.type) {
        const take = Math.min(player.inventory[i].count, remaining);
        player.inventory[i].count -= take;
        remaining -= take;
      }
    }
  }
  player.addItem(recipe.result, recipe.count);
  updateUI();
}

