  // Sun/Moon
  const celestialY = canvas.height * 0.15 + Math.cos(dayTime) * canvas.height * 0.1;
  if (dayPhase > 0.3) {
    ctx.fillStyle = '#ffdd44';
    ctx.beginPath();
